	&lt;array&gt;
		&lt;dict&gt;
			&lt;key&gt;Name&lt;/key&gt;
			&lt;string&gt;Configuration
  1&lt;/string&gt;
			&lt;key&gt;IsEnabled&lt;/key&gt;
			&lt;true/&gt;
