+import XCTest
+
+@MainActor
+final class BlueskyUITests: XCTestCase {
+    func testComposeAndPost() {
+        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
+        let openButton = app.alerts.buttons["Open"]
+        XCTAssertTrue(openButton.waitForExistence(timeout: 20))
+        openButton.tap()
+
+        let postText = "hello from the benchmark"
+        let composer = app.textViews.firstMatch
+        XCTAssertTrue(composer.waitForExistence(timeout: 20))
+        composer.tap()
+        composer.typeText(postText)
+
+        let postButton = app.buttons["Post"]
+        XCTAssertTrue(postButton.waitForExistence(timeout: 10))
+        postButton.tap()
+    }
+}
*** End Patch

